53	    this.controller = vscode.comments.createCommentController("codewalk", "CodeWalk");
54	    this.storeSub = this.expStore.onDidChange(id => this.onExplanationChanged(id));
55	  }
56	
57	  hasOpenThread(): boolean {
58	    return this.openThread !== undefined;
59	  }
60	
61	  openSegmentId(): string | undefined {
62	    return this.openSegment?.id;
63	  }
64	
65	  currentThreadBody(): string | undefined {
66	    if (!this.openThread) return undefined;
67	    const c = this.openThread.comments[0];
68	    if (!c) return undefined;
69	    const body = c.body;
70	    return typeof body === "string" ? body : body.value;
71	  }
72	
73	  collapse(): void {
74	    this.stopLoader();
75	    if (this.openTokenSource) {
76	      this.openTokenSource.cancel();
77	      this.openTokenSource.dispose();
78	      this.openTokenSource = undefined;
79	    }
80	    this.openThread?.dispose();
81	    this.openThread = undefined;
82	    this.openSegment = undefined;
