1	import * as vscode from "vscode";
2	import * as path from "node:path";
3	import type { SegmentStore } from "../engine/segmentStore";
4	import type { WalkSession } from "./walkSession";
5	
6	export class CodeWalkStatusBar implements vscode.Disposable {
7	  private readonly item: vscode.StatusBarItem;
8	  private readonly subs: vscode.Disposable[] = [];
9	
10	  constructor(
11	    private readonly walkSession: WalkSession,
12	    private readonly segStore: SegmentStore,
13	  ) {
14	    this.item = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 100);
15	    this.item.command = "codewalk.showBlockQuickPick";
16	    this.subs.push(walkSession.onDidChange(() => this.refresh()));
17	    this.subs.push(segStore.onDidChange(() => this.refresh()));
18	    this.subs.push(
19	      vscode.commands.registerCommand("codewalk.showBlockQuickPick", () => this.showQuickPick()),
20	    );
21	    this.refresh();
22	  }
23	
24	  private refresh(): void {
25	    if (!this.walkSession.isActive()) {
26	      this.item.hide();
27	      return;
28	    }
29	    const state = this.walkSession.state();
30	    const fileNum = state.activeFileIndex + 1;
31	    const fileTotal = state.fileQueue.length;
32	    const blockTotal = this.walkSession.activeSegmentCount();
33	    const blockNumStr = state.activeBlockIndex >= 0 ? String(state.activeBlockIndex + 1) : "—";
34	    const blockTotalStr = blockTotal > 0 ? String(blockTotal) : "—";
35	    this.item.text = `$(book) CodeWalk: File ${fileNum}/${fileTotal} | Block ${blockNumStr}/${blockTotalStr}`;
36	    this.item.tooltip = "Click to jump to a block";
37	    this.item.show();
38	  }
39	
40	  private async showQuickPick(): Promise<void> {
41	    const uri = this.walkSession.activeFile();
42	    if (!uri) return;
43	    const segs = this.segStore.get(uri);
44	    if (!segs || segs.length === 0) {
45	      vscode.window.showInformationMessage("CodeWalk: this file has no analyzed blocks yet.");
46	      return;
47	    }
48	    const items: Array<vscode.QuickPickItem & { segmentId: string }> = segs.map((s, i) => ({
49	      label: `${i + 1}. ${s.label}`,
50	      description: s.oneLiner,
51	      detail: `lines ${s.startLine}-${s.endLine} · ${s.difficulty}`,
52	      segmentId: s.id,
53	    }));
54	    const picked = await vscode.window.showQuickPick(items, {
55	      placeHolder: `${path.basename(uri.fsPath)} — pick a block to jump to`,
56	      matchOnDescription: true,
57	      matchOnDetail: true,
58	    });
59	    if (!picked) return;
60	    const idx = segs.findIndex(s => s.id === picked.segmentId);
61	    if (idx < 0) return;
62	    this.walkSession.applyTarget({
63	      uri,
