      store,
      explanationStore,
      {
        adapter,
        promptsDir: context.asAbsolutePath("prompts"),
        preset: resolved.backend,
        promptVersion: EXPLANATION_PROMPT_VERSION,
        logger,
        structuredOutputMode: resolved.structuredOutputMode,
        prefetchQueue,
        prefetchNeighborsOnClick,
