1	import * as vscode from "vscode";
2	import type { Explanation } from "../types";
3	import { EXPLANATION_PROMPT_VERSION } from "./explanationAgent";
4	
5	const KEY_PREFIX = "explanation:";
6	
7	function keyFor(preset: string, promptVersion: string, segmentId: string): string {
8	  return `${KEY_PREFIX}${preset}:${promptVersion}:${segmentId}`;
9	}
10	
11	function isDoneExplanation(x: unknown): x is Explanation {
12	  if (!x || typeof x !== "object") return false;
13	  const o = x as Explanation;
14	  return (
15	    typeof o.segmentId === "string"
16	    && typeof o.summary === "string"
17	    && o.renderState === "done"
18	  );
19	}
20	
21	export class ExplanationStore implements vscode.Disposable {
22	  private readonly mem = new Map<string, Explanation>();
23	  private readonly _onDidChange = new vscode.EventEmitter<string>();
24	  readonly onDidChange = this._onDidChange.event;
25	
26	  constructor(
27	    private readonly context: vscode.ExtensionContext,
28	    private readonly logger?: (msg: string) => void,
29	    private readonly currentPromptVersion: string = EXPLANATION_PROMPT_VERSION,
30	  ) {
31	    this.rehydrate();
32	  }
33	
34	  private rehydrate(): void {
35	    const state = this.context.globalState;
36	    for (const key of state.keys()) {
37	      if (!key.startsWith(KEY_PREFIX)) continue;
38	      const parts = key.slice(KEY_PREFIX.length).split(":");
39	      if (parts.length < 3) {
40	        this.logger?.(`[explanationStore] WARN dropping malformed key ${key}`);
41	        void state.update(key, undefined);
42	        continue;
43	      }
44	      const [, promptVersion] = parts;
45	      if (promptVersion !== this.currentPromptVersion) {
46	        this.logger?.(`[explanationStore] dropping stale-version entry ${key}`);
47	        void state.update(key, undefined);
48	        continue;
49	      }
