import * as vscode from "vscode";
import type { Explanation } from "../types";
import { EXPLANATION_PROMPT_VERSION } from "./explanationAgent";

const KEY_PREFIX = "explanation:";

function keyFor(preset: string, promptVersion: string, segmentId: string): string {
  return `${KEY_PREFIX}${preset}:${promptVersion}:${segmentId}`;
}

function isDoneExplanation(x: unknown): x is Explanation {
  if (!x || typeof x !== "object") return false;
  const o = x as Explanation;
  return (
    typeof o.segmentId === "string"
    && typeof o.summary === "string"
    && o.renderState === "done"
  );
}

export class ExplanationStore implements vscode.Disposable {
  private readonly mem = new Map<string, Explanation>();
  private readonly _onDidChange = new vscode.EventEmitter<string>();
  readonly onDidChange = this._onDidChange.event;

  constructor(
    private readonly context: vscode.ExtensionContext,
    private readonly logger?: (msg: string) => void,
    private readonly currentPromptVersion: string = EXPLANATION_PROMPT_VERSION,
  ) {
    this.rehydrate();
  }

  private rehydrate(): void {
    const state = this.context.globalState;
    for (const key of state.keys()) {
      if (!key.startsWith(KEY_PREFIX)) continue;
      const parts = key.slice(KEY_PREFIX.length).split(":");
      if (parts.length < 3) {
        this.logger?.(`[explanationStore] WARN dropping malformed key ${key}`);
        void state.update(key, undefined);
        continue;
      }
      const [, promptVersion] = parts;
      if (promptVersion !== this.currentPromptVersion) {
        this.logger?.(`[explanationStore] dropping stale-version entry ${key}`);
        void state.update(key, undefined);
        continue;
      }
      const value = state.get<unknown>(key);
      if (!isDoneExplanation(value)) {
        this.logger?.(`[explanationStore] WARN dropping malformed entry ${key}`);
        void state.update(key, undefined);
        continue;
      }
      this.mem.set(key, value);
    }
  }

  get(segmentId: string, preset: string, promptVersion: string): Explanation | undefined {
    return this.mem.get(keyFor(preset, promptVersion, segmentId));
  }

  set(
    segmentId: string,
    preset: string,
    promptVersion: string,
    exp: Explanation,
  ): void {
    const key = keyFor(preset, promptVersion, segmentId);
    this.mem.set(key, exp);
    this._onDidChange.fire(segmentId);
    if (exp.renderState === "done") {
      this.context.globalState.update(key, exp).then(
        () => { /* ok */ },
        (err) => this.logger?.(`[explanationStore] WARN persistence failed: ${(err as Error).message}`),
      );
    }
  }

  clear(): void {
    const keys = Array.from(this.mem.keys());
    this.mem.clear();
    for (const key of keys) {
      void this.context.globalState.update(key, undefined);
      const id = key.split(":").pop()!;
      this._onDidChange.fire(id);
    }
  }

  dispose(): void {
    this.mem.clear();
    this._onDidChange.dispose();
  }
}

You are CodeWalk's explanation agent. Given ONE code block plus its surrounding file, produce a single short prose summary.

Target reader: an entry-level programmer skimming an unfamiliar codebase. They want a quick, specific paragraph — not a textbook chapter. Help them decide "do I need to read this block carefully or skim it?" in seconds.

## Rules

- Output a single `summary` string, 3–5 sentences total, max ~600 characters.
- First sentence: state what the block does in programmer terms (the WHY behind it). Do not restate what the literal code says.
- If the block does I/O (network, database, file, subprocess), name the SPECIFIC endpoint, table name, or file path inside the summary — not "a database" or "the API".
- If the block has a non-obvious risk (race condition, injection, unhandled error path, off-by-one, assumption that callers must hold), append a short `Watch …` clause naming the specific concern. Reference a line number where helpful.
- No bullets, no Markdown headers, no code fences, no `Here is …` preamble, no closing remarks.
- Plain prose only. The renderer will not interpret Markdown beyond what's in the string.
- Do NOT echo the block's label or one-liner — they are shown above the panel already.

Trivial blocks (imports, type aliases, config literals) are handled by the orchestrator without calling you. If you see one anyway, write a single sentence about its role in the file.

## Response Format

Respond with ONLY the raw JSON object matching the schema. No preamble, no closing remarks, no Markdown fence around the JSON.

Schema:
{
  "summary": "string"
}

