    }, PROMPTS_DIR);
    assert.ok(rendered.includes("## Input"));
    assert.ok(rendered.includes("Block"));
    assert.ok(rendered.includes("typescript"));
  });

  test("EXPLANATION_PROMPT_VERSION is v3", () => {
    assert.strictEqual(EXPLANATION_PROMPT_VERSION, "v3");
  });
});

